<template>
  <el-main>
    <el-row justify="end">
      <el-button type="primary" @click="addClient">New client</el-button>
    </el-row>
    <el-table :data="tableData" :default-sort="{ prop: 'name' }" style="width: 100%">
      <el-table-column prop="name" label="Name" width="180" :formatter="clientLabel" :sort-by="clientLabelUppercase">
      </el-table-column>
      <el-table-column prop="email" label="Email"> </el-table-column>
      <el-table-column prop="phone" label="Phone"> </el-table-column>
      <el-table-column prop="address" label="Address"> </el-table-column>
      <el-table-column align="right">
        <template #header>
          <el-input v-model="search" placeholder="Type to search" />
        </template>
        <template #default="scope">
          <el-button :icon="Edit" circle @click="handleEdit(scope.row)" />
          <el-button :icon="Delete" circle :disabled="invoiceCount(scope.row.id) > 0"
            @click="deleteClient(scope.row.id)" />
        </template>
      </el-table-column>
    </el-table>

    <el-dialog title="Client details" v-model="dialogVisible" width="50%">
      <el-form label-width="120px">
        <el-form-item label="Company">
          <el-input v-model="editClient.company"></el-input>
        </el-form-item>
        <el-form-item label="Name">
          <el-input v-model="editClient.name"></el-input>
        </el-form-item>
        <el-form-item label="Email">
          <el-input v-model="editClient.email"></el-input>
        </el-form-item>
        <el-form-item label="Phone">
          <el-input v-model="editClient.phone"></el-input>
        </el-form-item>
        <el-form-item label="Address">
          <el-input v-model="editClient.address"></el-input>
        </el-form-item>
        <el-form-item label="Language">
          <el-select v-model="editClient.language">
            <el-option label="English" value="English" />
            <el-option label="French" value="French" />
          </el-select>
        </el-form-item>
      </el-form>
      <template #footer>
        <span class="dialog-footer">
          <el-button @click="cancelEdit">Cancel</el-button>
          <el-button type="primary" @click="confirmEdit">Confirm</el-button>
        </span>
      </template>
    </el-dialog>
  </el-main>
</template>

<script>
import { Edit, Delete } from '@element-plus/icons-vue'

function uuidv4() {
  return ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, c =>
    (
      c ^
      (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (c / 4)))
    ).toString(16)
  );
}
class Client {
  constructor() {
    this.id = uuidv4();
    this.company = "";
    this.name = "";
    this.email = "";
    this.phone = "";
    this.address = "";
    this.language = "English"
  }
}

export default {
  name: "InvoiceClients",
  props: {
    state: Object
  },
  data() {
    return {
      Edit,
      Delete,
      dialogVisible: false,
      editClient: false,
      search: ""
    };
  },
  computed: {
    clients() {
      return this.state.clients;
    },
    tableData() {
      return this.clients.filter(
        client =>
          !this.search ||
          JSON.stringify(client)
            .toLowerCase()
            .includes(this.search.toLowerCase())
      );
    }
  },
  methods: {
    addClient() {
      this.editClient = new Client();
      this.dialogVisible = true;
    },
    cancelEdit() {
      this.dialogVisible = false;
      this.editClient = false;
    },
    confirmEdit() {
      this.$emit("saveClient", this.editClient);
      this.cancelEdit();
    },
    handleEdit(client) {
      this.editClient = JSON.parse(JSON.stringify(client));
      this.dialogVisible = true;
    },
    invoiceCount(id) {
      return this.state.invoices.filter(invoice => invoice.client === id)
        .length;
    },
    deleteClient(id) {
      this.$confirm(
        "This will permanently delete the client. Continue?",
        "Warning",
        {
          confirmButtonText: "OK",
          cancelButtonText: "Cancel",
          type: "warning"
        }
      )
        .then(() => {
          this.$emit("deleteClient", id);
        })
        .catch(() => {
          // cancelled - don't delete it
        });
    },
    clientLabel(client) {
      let label = client.company || client.name;
      if (client.company && client.name) {
        label += ` (${client.name})`;
      }
      return label;
    },
    clientLabelUppercase(client) {
      return this.clientLabel(client).toUpperCase();
    }
  }
};
</script>

<style scoped></style>
