<template>
  <div id="app">
    <div v-if="isSignedIn" style="height: 100%">
      <el-container style="height: 100%">
        <el-main class="app" style="padding: 0; height: 100%">
          <el-container style="height: 100%">
            <el-aside width="200px" style="height: 100%">
              <el-menu default-active="3" style="height: 100%">
                <el-menu-item @click="signout" index="4">
                  <el-icon>
                    <Back />
                  </el-icon>
                  Sign out
                </el-menu-item>
                <el-menu-item @click="navSection = 'settings'" index="1">
                  <el-icon>
                    <Setting />
                  </el-icon>
                  Settings
                </el-menu-item>
                <el-menu-item @click="navSection = 'clients'" index="2">
                  <el-icon>
                    <User />
                  </el-icon>
                  Clients
                </el-menu-item>
                <el-menu-item @click="navSection = 'invoices'" index="3">
                  <el-icon>
                    <Tickets />
                  </el-icon>
                  Invoices
                </el-menu-item>
                <el-menu-item @click="navSection = 'summary'" index="4">
                  <el-icon>
                    <DataLine />
                  </el-icon>
                  Summary
                </el-menu-item>
                <el-menu-item @click="copyData" index="5">
                  <el-icon>
                    <CopyDocument />
                  </el-icon>
                  Copy data
                </el-menu-item>
              </el-menu>
            </el-aside>

            <el-container>
              <invoice-settings v-if="navSection === 'settings'" :state="state" />
              <invoice-clients @saveClient="saveClient" @deleteClient="deleteClient" v-if="navSection === 'clients'"
                :state="state" />
              <invoices @saveInvoice="saveInvoice" @deleteInvoice="deleteInvoice" @printInvoice="print"
                v-if="navSection === 'invoices'" :state="state" />
              <Summary v-if="navSection === 'summary'" :state="state" />
            </el-container>
          </el-container>
        </el-main>
      </el-container>
      <printable-invoice v-if="printInvoice" :state="state" :invoice="printInvoice" />
    </div>
    <div v-else>
      <el-container>
        <el-main style="
            margin-top: 60px;
            text-align: center;
            color: #ccc;
            line-height: 3em;
          ">
          Bonjour Clément!
          <br />
          Pour commencer à facturer, connectez-vous avec Google Drive
          <br />
          <el-button @click="signin">No panic</el-button>
        </el-main>
      </el-container>
    </div>
  </div>
</template>

<script>
import InvoiceSettings from "./components/InvoiceSettings.vue";
import InvoiceClients from "./components/InvoiceClients.vue";
import Invoices from "./components/Invoices.vue";
import PrintableInvoice from "./components/PrintableInvoice.vue";
import Summary from "./components/Summary.vue";
import { Back, Setting, User, Tickets, DataLine, CopyDocument } from '@element-plus/icons-vue'

window.onafterprint = () => {
  document.title = "Invoices";
};

class DefaultState {
  constructor() {
    this.settings = {
      name: "",
      businessName: "",
      siret: "",
      includeVat: false,
      address: "",
      email: "",
      phone: "",
      paymentDetails: {
        name: "",
        sortCode: "",
        accountNumber: "",
        swift: "",
        iban: "",
        ukIban: "",
        bic: "",
        ukBankName: "",
        ukBankAddress: "",
        frenchBankName: "",
        frenchBankAddress: "",
      }
    };
    this.clients = [];
    this.invoices = [];
  }
}
export default {
  components: {
    InvoiceSettings,
    InvoiceClients,
    Invoices,
    PrintableInvoice,
    Summary,
    Back,
    Setting,
    User,
    Tickets,
    DataLine,
    CopyDocument,
  },
  data() {
    return {
      isSignedIn: false,
      state: new DefaultState(),
      navSection: "invoices",
      printInvoice: null
    };
  },
  watch: {
    state: {
      deep: true,
      handler() {
        this.save();
      }
    }
  },
  methods: {
    copyData() {
      navigator.clipboard.writeText(JSON.stringify(this.state)).then(
        () => {
          this.$message.info("All data copied to clipboard");
        },
        err => {
          this.$message.error(err);
        }
      );
    },
    saveClient(client) {
      const index = this.state.clients.findIndex(existing => {
        return existing.id === client.id;
      });
      if (index === -1) {
        this.state.clients.push(client);
      } else {
        this.state.clients[index] = client;
      }
    },
    saveInvoice(invoice) {
      const index = this.state.invoices.findIndex(existing => {
        return existing.id === invoice.id;
      });
      if (index === -1) {
        this.state.invoices.push(invoice);
      } else {
        this.state.invoices[index] = invoice;
      }
    },
    deleteClient(id) {
      const index = this.state.clients.findIndex(client => {
        return client.id === id;
      });
      if (index != -1) {
        this.state.clients.splice(index, 1);
      }
    },
    deleteInvoice(id) {
      const index = this.state.invoices.findIndex(invoice => {
        return invoice.id === id;
      });
      if (index != -1) {
        this.state.invoices.splice(index, 1);
      }
    },
    authorise() {
      gapi.load("client:auth2", this.initClient);
    },
    initClient() {
      const client_id =
        "989846409282-j3lkg93rcn1047hu2hh0ko5pg8rst3t3.apps.googleusercontent.com";
      const scope = "https://www.googleapis.com/auth/drive.appdata";
      gapi.client.init({ client_id, scope }).then(
        () => {
          // Listen for sign-in state changes.
          gapi.auth2
            .getAuthInstance()
            .isSignedIn.listen(this.updateSigninStatus);

          // Handle the initial sign-in state.
          this.updateSigninStatus(
            gapi.auth2.getAuthInstance().isSignedIn.get()
          );
        },
        error => {
          this.$message.error(JSON.stringify(error, null, 2));
        }
      );
    },
    updateSigninStatus(isSignedIn) {
      this.isSignedIn = isSignedIn;
      if (isSignedIn) {
        this.read();
      } else {
        this.state = new DefaultState();
      }
    },
    loadDriveAPI() {
      return gapi.client.load("drive", "v3");
    },
    getFileId() {
      return gapi.client.drive.files
        .list({
          q: 'name="invoices.json"',
          spaces: "appDataFolder",
          fields: "files(id)"
        })
        .then(response => {
          if (response.result.files.length == 0) {
            return this.create();
          }
          return response.result.files[0].id;
        });
    },
    prepare() {
      return this.loadDriveAPI().then(this.getFileId);
    },
    create() {
      return gapi.client.drive.files
        .create({
          fields: "id",
          resource: { name: "invoices.json", parents: ["appDataFolder"] }
        })
        .then(function (response) {
          return response.result.id;
        });
    },
    read() {
      return this.prepare().then(id => {
        return gapi.client.drive.files
          .get({ fileId: id, alt: "media" })
          .then(file => {
            if (file.body.length > 0) {
              this.state = JSON.parse(file.body);
              this.state.invoices.forEach(obj => {
                obj.paymentTermsDays = obj.net30 ? 30 : null;
                delete obj.net30;
              });

            }
          });
      });
    },
    save() {
      if (!this.isSignedIn) {
        return;
      }
      this.prepare().then(id => {
        return gapi.client.request({
          path: "/upload/drive/v3/files/" + id,
          method: "PATCH",
          params: { uploadType: "media" },
          body: JSON.stringify(this.state)
        });
      });
    },
    signin() {
      confirm("Please confirm there is no panic")
      gapi.auth2.getAuthInstance().signIn();
    },
    signout() {
      gapi.auth2.getAuthInstance().signOut();
    },
    print(invoice) {
      this.printInvoice = invoice;
      document.title = invoice.reference;
      this.$nextTick(() => {
        window.print();
      });
    }
  },
  mounted() {
    window.addEventListener("google-loaded", this.authorise);
  }
};
</script>

<style>
body {
  margin: 0;
  font-family: "Montserrat";
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#app {
  color: #2c3e50;
  height: 100vh;
}

@media print {
  .app {
    display: none;
  }

  @page {
    size: auto;
    margin: 0;
  }
}
</style>
